jest.mock('electron', () => ({ ipcMain: { handle: jest.fn() } }));
jest.mock('./private/private-windows', () => ({ isPrivateWebContents: jest.fn(() => false) }));
jest.mock('./spaces/anchors', () => ({ establishTrust: jest.fn() }));

const { loadVeritas } = require('./spaces/veritas');
const { establishTrust } = require('./spaces/anchors');
const { createSpacesResolver, forgetSpacesSession, resolveSpace } = require('./spaces-resolver');
const generated = require('../../test/fixtures/spaces/generated-members.json');

// Generated by the pinned Rust verifier on a hosted runner. The actual shipped
// wasm verifies every answer here with VERIFY_DEFAULT, including the member's
// committed genesis key and the exact name on its signed record set.
const lib = loadVeritas();
const hex = (value) => Buffer.from(value, 'hex');
const RELAYS = [
  { name: 'relay-a', url: 'https://relay-a.test' },
  { name: 'relay-b', url: 'https://relay-b.test' },
];
const both = (answer) => [answer, answer];

function message(fixture, variant = 'website') {
  const value = new lib.Message(hex(fixture.message));
  try {
    value.setRecords(fixture.handle, hex(fixture.records[variant]));
    return Buffer.from(value.toBytes());
  } finally {
    value.free();
  }
}

function setup(fixture, answers = both(message(fixture)), options = {}) {
  const fetch = jest.fn(async (url) => {
    const index = RELAYS.findIndex((relay) => url.startsWith(`${relay.url}/query?q=`));
    if (index < 0) throw new Error(`unexpected request ${url}`);
    const answer = answers[index];
    if (answer instanceof Error) throw answer;
    return new Response(answer);
  });
  const trust = jest.fn(async () => ({
    root: 'member-fixture-root',
    height: fixture.anchors[0].block.height,
    entries: fixture.anchors,
    relays: RELAYS,
  }));
  return { fetch, trust, resolver: createSpacesResolver({ fetch, trust, ...options }) };
}

describe('verified member-name browsing', () => {
  const fixture = generated.sovereign;

  test('a finalized member opens its own signed HTTPS website, with the full name queried', async () => {
    const { resolver, fetch } = setup(fixture);
    await expect(resolver.resolve('Member@MemberSpace')).resolves.toEqual({
      type: 'ok',
      handle: fixture.handle,
      url: 'https://example.com/member',
      anchorHeight: 145,
      trustRoot: 'member-fixture-root',
    });
    for (const relay of RELAYS) {
      expect(fetch).toHaveBeenCalledWith(
        `${relay.url}/query?q=member%40memberspace`,
        expect.anything()
      );
    }
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  test.each([
    ['http', 'INVALID_WEBSITE_RECORD'],
    ['two-values', 'INVALID_WEBSITE_RECORD'],
    ['no-website', 'NO_WEBSITE_RECORD'],
    ['foreign-key', 'NO_WEBSITE_RECORD'],
    ['other-name', 'NO_WEBSITE_RECORD'],
    ['parent-name', 'NO_WEBSITE_RECORD'],
    ['bad-signature', 'NO_WEBSITE_RECORD'],
  ])('member records %s are refused as %s, without using the parent website', async (variant, reason) => {
    const { resolver } = setup(fixture, both(message(fixture, variant)));
    await expect(resolver.resolve(fixture.handle)).resolves.toMatchObject({
      type: 'refused', handle: fixture.handle, reason,
    });
  });

  test.each(['pending', 'dependent'])('%s certificates cannot open even a valid signed website', async (kind) => {
    const current = generated[kind];
    const { resolver } = setup(current);
    await expect(resolver.resolve(current.handle)).resolves.toMatchObject({
      type: 'refused', handle: current.handle, reason: 'MEMBER_NOT_FINAL',
    });
  });

  test('the newest member record sequence wins in either relay order', async () => {
    for (const variants of [['website', 'website-seq2'], ['website-seq2', 'website']]) {
      const { resolver } = setup(fixture, variants.map((variant) => message(fixture, variant)));
      await expect(resolver.resolve(fixture.handle)).resolves.toMatchObject({
        type: 'ok', url: 'https://example.org/member-next',
      });
    }
  });

  test('a valid parent website cannot replace the absent member proof, and absence is not cached', async () => {
    const { resolver, fetch } = setup(fixture, both(hex(fixture.parentOnlyMessage)));
    for (let i = 0; i < 2; i++) {
      await expect(resolver.resolve(fixture.handle)).resolves.toEqual({
        type: 'refused', handle: fixture.handle, reason: 'SPACE_NOT_FOUND',
      });
    }
    expect(fetch).toHaveBeenCalledTimes(4);
  });

  test('a substituted genesis key invalidates the committed member proof', async () => {
    const { resolver, trust } = setup(fixture, both(hex(fixture.wrongGenesisMessage)));
    await expect(resolver.resolve(fixture.handle)).resolves.toMatchObject({
      type: 'error', reason: 'PROOF_UNVERIFIED',
    });
    expect(trust).toHaveBeenCalledTimes(2);
  });

  test.each(['truncated', 'wrong-anchors'])('%s member proofs never yield a website', async (kind) => {
    const answers = both(kind === 'truncated' ? message(fixture).subarray(0, 80) : message(fixture));
    const current = kind === 'wrong-anchors' ? generated.pending : fixture;
    const { resolver } = setup(current, answers);
    await expect(resolver.resolve(fixture.handle)).resolves.toMatchObject({
      type: 'error', reason: 'PROOF_UNVERIFIED',
    });
  });

  test('one proving relay cannot overcome a failing relay or parent-only answer', async () => {
    for (const answer of [new Error('net::ERR_CONNECTION_RESET'), hex(fixture.parentOnlyMessage)]) {
      const { resolver, trust } = setup(fixture, [message(fixture), answer]);
      await expect(resolver.resolve(fixture.handle)).resolves.toMatchObject({
        type: 'error', reason: 'PROOF_UNCONFIRMED',
      });
      expect(trust).toHaveBeenCalledTimes(2);
    }
  });

  test('another member cannot use this member proof or its cached result', async () => {
    const { resolver, fetch } = setup(fixture);
    await expect(resolver.resolve(fixture.handle)).resolves.toMatchObject({ type: 'ok' });
    const other = await resolver.resolve('other@memberspace');
    expect(other.type).not.toBe('ok');
    expect(other.handle).toBe('other@memberspace');
    expect(fetch.mock.calls.some(([url]) => url.endsWith('q=other%40memberspace'))).toBe(true);
  });

  test('normalized names share only a short-lived result in their own resolver', async () => {
    let clock = 1_000_000;
    const first = setup(fixture, both(message(fixture)), { now: () => clock });
    const second = setup(fixture, both(message(fixture, 'no-website')));
    await expect(first.resolver.resolve(fixture.handle)).resolves.toMatchObject({ type: 'ok' });
    await first.resolver.resolve('Member@MemberSpace');
    expect(first.fetch).toHaveBeenCalledTimes(2);
    await expect(second.resolver.resolve(fixture.handle)).resolves.toMatchObject({
      type: 'refused', reason: 'NO_WEBSITE_RECORD',
    });
    expect(second.fetch).toHaveBeenCalledTimes(2);
    clock += 30_001;
    await first.resolver.resolve(fixture.handle);
    expect(first.fetch).toHaveBeenCalledTimes(4);
  });

  test('the production session entry point isolates member results and forgets retired sessions', async () => {
    establishTrust.mockImplementation(setup(fixture).trust);
    const normal = { fetch: setup(fixture).fetch };
    const privateSession = { fetch: setup(fixture, both(message(fixture, 'no-website'))).fetch };
    await expect(resolveSpace(normal, fixture.handle)).resolves.toMatchObject({ type: 'ok' });
    await expect(resolveSpace(privateSession, fixture.handle)).resolves.toMatchObject({
      type: 'refused', reason: 'NO_WEBSITE_RECORD',
    });
    expect(normal.fetch).toHaveBeenCalledTimes(2);
    expect(privateSession.fetch).toHaveBeenCalledTimes(2);
    await resolveSpace(privateSession, fixture.handle);
    expect(privateSession.fetch).toHaveBeenCalledTimes(2);
    forgetSpacesSession(privateSession);
    await resolveSpace(privateSession, fixture.handle);
    expect(privateSession.fetch).toHaveBeenCalledTimes(4);
    expect(normal.fetch).toHaveBeenCalledTimes(2);
    forgetSpacesSession(normal);
    forgetSpacesSession(privateSession);
  });
});

describe('member finality quorum policy', () => {
  // Isolate selection after verification: the cryptographic cases above prove
  // real sovereign, pending and dependent certificates. These plain zones make
  // conflicting relay state/keys deterministic without pretending they are
  // additional signed chain fixtures.
  function policyResolver(zones) {
    let next = 0;
    class Owned { free() {} }
    class Veritas extends Owned {
      verifyWithOptions() {
        const zone = zones[next++ % zones.length];
        return { zones: () => [zone], free() {} };
      }
    }
    const policyLib = () => ({
      Anchors: Owned, Message: Owned, Veritas,
      QueryContext: class extends Owned { addRequest() {} },
      VERIFY_DEFAULT: () => 0,
      zoneIsBetterThan: (a, b) => a.anchor > b.anchor,
    });
    return setup(generated.sovereign, both(Buffer.from('policy only')), { lib: policyLib }).resolver;
  }
  const zone = (anchor, key, sovereignty) => ({
    handle: 'member@memberspace', canonical: 'member@memberspace',
    anchor, script_pubkey: key, sovereignty, records: [],
  });

  test('one sovereign proof does not finalize a two-relay owner quorum', async () => {
    const resolver = policyResolver([
      zone(145, 'current-key', 'sovereign'), zone(146, 'current-key', 'pending'),
    ]);
    await expect(resolver.resolve('member@memberspace')).resolves.toMatchObject({
      type: 'refused', reason: 'MEMBER_NOT_FINAL',
    });
  });

  test('an older finalized owner cannot override the newest proved owner key', async () => {
    const resolver = policyResolver([
      zone(145, 'previous-key', 'sovereign'), zone(146, 'current-key', 'pending'),
    ]);
    await expect(resolver.resolve('member@memberspace')).resolves.toMatchObject({
      type: 'error', reason: 'PROOF_UNCONFIRMED',
    });
  });
});
